import React, { Component } from 'react';
export default  class Resume extends Component {
  render() {
    let resumeData = this.props.resumeData;
    return (
      <section id="resume">

         <div className="row education">

            <div className="three columns header-col">
               <h1><span>Education</span></h1>
            </div>

            <div className="nine columns main-col">
              {
                resumeData.education && resumeData.education.map((item,index)=>{
                  return(
                    <div className="row item" key={index}>
                       <div className="twelve columns">
                          <h3>{item.UniversityName}</h3>
                          <p className="info">
                          {item.specialization}
                          <span>&bull;</span> <em className="date">{item.MonthOfPassing} {item.YearOfPassing}</em></p>
                          <p>
                          {item.Achievements}
                          </p>
                       </div>
                    </div>
                  )
                })
              }
            </div>
         </div>
        <div className="row work">
            <div className="three columns header-col">
               <h1><span>Work</span></h1>
            </div>

            <div className="nine columns main-col">
              {
                resumeData.work && resumeData.work.map((item,index) => {
                  return(
                    <div>
                    <div className="row item" key={index}>
                       <div className="twelve columns">
                          <h3>{item.CompanyName}</h3>
                          <p className="info">
                          {item.specialization}
                          <span>&bull;</span> <em className="date">{item.MonthOfLeaving} {item.YearOfLeaving}</em></p>
                          <p>
                          {item.Achievements}
                          </p>
                       </div>
                    </div>
                </div>  
                  )
                })  
              }
            </div>
            <div>
            <div className="three columns header-col">
               <h1><span>Projects</span></h1>
            </div>    
            <div className="nine columns main-col">
            {
                resumeData.work && resumeData.work.map((item,index) => {
                  return(
                    <div>
                    <div className="row item" key={index}>
                       <div className="twelve columns">
                        {
                          item.projects && item.projects.map((it,idx)=>{
                            return(
                              <div style={{marginTop: "20px"}}>
                                <h4>{it.Title}</h4>
                                <p className="info">
                                {it.Duration}
                                <span>&bull;</span> <em className="date">{it.Start} ~ {it.End}</em></p>
                                <div>
                                  {it.Content}
                                </div>
                                {
                                  it.Works.map((it,idx)=>{
                                    return(
                                      <div>
                                        <p className="info">수행 업무: {it.Title}</p>
                                      {
                                        
                                        it.Content.map((it,idx)=>{
                                          return(
                                            <li style={{marginTop:"10px"}}>{it}</li>
                                          )
                                        })
                                      }
                                      </div>
                                    )
                                  })
                                  
                                }
                                
                                {
                                  // it.Works.Content.map((it,idx)=>{
                                  //   return(
                                  //     <li style={{marginTop:"10px"}}>{it}</li>
                                  //   )
                                  // })
                                }

                                {/* <div style={{marginTop:"10px"}}>
                                <p className="info">
                                 {it.Language.lan}
                                </p>
                                </div>
                                <div>
                                  {
                                  it.Language && it.Language.skill.map((it,idx)=>{
                                    return(                                          
                                            <li style={{marginTop:"10px"}}>{it}</li>

                                    )
                                  })
                                  }
                                </div> */}
                              </div>
                              
                            )
                          })
                        }
                       </div>
                    </div>
                </div>  
                  )
                })  
              }
            </div>
          </div>         
         </div>
         
         <div className="row certificate">
            <div className="three columns header-col">
               <h1><span>CERTIFICATE</span></h1>
            </div>

            <div className="nine columns main-col">
              {
                resumeData.work && resumeData.certificate.map((item,index) => {
                  return(
                    <div className="row item" key={index}>
                       <div className="twelve columns">
                          <h3>{item.CompanyName}</h3>
                          <p className="info">
                          {item.specialization}
                          <span>&bull;</span> <em className="date">{item.MonthOfLeaving} {item.YearOfLeaving}</em></p>
                          <p>
                          {item.Achievements}
                          </p>
                       </div>
                    </div>
                  )
                })
              }
            </div>
            
         </div>
         


         <div className="row skill">

            <div className="three columns header-col">
               <h1><span>Skills</span></h1>
            </div>

            <div className="nine columns main-col">

               <p>
               {resumeData.skillsDescription}
               </p>

   				<div className="bars">

   				   <ul className="skills">
                {
                  resumeData.skills && resumeData.skills.map((item,index) => {
                    return(
                      <li key={index}>
                      <span className={`bar-expand ${item.skillname.toLowerCase()}`}>
                      </span><em>{item.skillname}</em>
                      </li>
                    )
                  })
                }

   					</ul>

   				</div>

   			</div>

         </div>

      </section>
    );
  }
}